exercise.solution:
registry = []


def tracked(func):
    """Record func's name in registry once, when it is decorated,
    and count every call in wrapper.calls."""
    registry.append(func.__name__)

    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

tests.code:
registry.clear()
@tracked
def ping():
    return "pong"
assert registry == ["ping"], f"registry is {registry!r} right after decorating"

@tracked
def add(a, b):
    return a + b
add(1, 2)
add(3, 4)
assert add.calls == 2, f"calls is {add.calls}"

registry.clear()
@tracked
def f():
    return 1
f(); f(); f()
assert registry == ["f"], f"registry is {registry!r}"

@tracked
def greet(name, punct="!"):
    return "hi " + name + punct
assert greet("ada", punct="?") == "hi ada?"

@tracked
def a():
    pass
@tracked
def b():
    pass
a(); a(); b()
assert (a.calls, b.calls) == (2, 1), (a.calls, b.calls)
